def retrieve(query: str, k: int = 5, date_from: str = None):
    query_vector = embed(query)

    filter_expr = {}
    if date_from:
        filter_expr = {"date": {"$gte": date_from}}

    results = index.query(
        vector=query_vector,
        top_k=k,
        filter=filter_expr,
        include_metadata=True
    )

    return [
        {"text": match.metadata["text"], "score": match.score, "source": match.metadata["source"]}
        for match in results.matches
    ]

chunks = retrieve("how long do I have to request a refund?", k=3, date_from="2024-01")
for c in chunks:
    print(f"[{c['score']:.3f}] {c['source']}: {c['text']}")
